    required this.installed,
    required this.deployed,
    required this.version,
    this.variant,
    required this.englishAvailable,
    this.latestVersion,
  });

  @override
  int get hashCode =>
      installed.hashCode ^
      deployed.hashCode ^
      version.hashCode ^
      variant.hashCode ^
      englishAvailable.hashCode ^
      latestVersion.hashCode;

  @override
